def solve_cvrp(instance):
    # Minimal, deterministic CVRP solver returning routes as lists of 0-based customer indices
    def get_field(obj, key, default=None):
        if isinstance(obj, dict) and key in obj:
            return obj[key]
        if hasattr(obj, key):
            return getattr(obj, key)
        return default

    n = get_field(instance, 'num_customers', 0)
    demands = get_field(instance, 'demands', None)
    if demands is None:
        demands = [0] * n
    capacity = get_field(instance, 'capacity', 0)
    coords = get_field(instance, 'coords', None)
    use_coords = coords is not None and len(coords) == n

    customers = [(i, demands[i]) for i in range(n)]
    customers.sort(key=lambda x: (-x[1], x[0]))

    routes = []
    current_route = []
    current_load = 0

    for cid, d in customers:
        if current_load + d <= capacity:
            current_route.append(cid)
            current_load += d
        else:
            if current_route:
                routes.append(current_route)
            current_route = [cid]
            current_load = d

    if current_route:
        routes.append(current_route)

    def dist(a, b):
        if use_coords:
            x1, y1 = coords[a]
            x2, y2 = coords[b]
            dx = x1 - x2
            dy = y1 - y2
            return (dx*dx + dy*dy) ** 0.5
        else:
            return abs(a - b)

    def route_distance(route):
        if not route:
            return 0.0
        total = 0.0
        prev = route[0]
        for cid in route[1:]:
            total += dist(prev, cid)
            prev = cid
        return total

    improved = True
    while improved:
        improved = False
        for i in range(len(routes) - 1):
            r1 = routes[i]
            r2 = routes[i+1]
            if not r1 or not r2:
                continue

            cand1 = r1[:-1]
            moved = r1[-1]
            new_r2 = [moved] + r2
            d_move = demands[moved]
            load_r1 = sum(demands[c] for c in cand1) if cand1 else 0
            load_r2 = sum(demands[c] for c in r2)
            if load_r1 + d_move <= capacity and load_r2 <= capacity:
                new_routes = routes[:i] + [cand1, new_r2] + routes[i+2:]
                old_dist = sum(route_distance(r) for r in routes)
                new_dist = sum(route_distance(r) for r in new_routes)
                if new_dist < old_dist:
                    routes = new_routes
                    improved = True
                    break

            cand2 = r2[1:]
            moved2 = r2[0]
            new_r1 = r1 + [moved2]
            load_r1_new = sum(demands[c] for c in new_r1)
            load_r2_new = sum(demands[c] for c in cand2)
            if load_r1_new <= capacity and load_r2_new <= capacity:
                new_routes = routes[:i] + [new_r1, cand2] + routes[i+2:]
                old_dist = sum(route_distance(r) for r in routes)
                new_dist = sum(route_distance(r) for r in new_routes)
                if new_dist < old_dist:
                    routes = new_routes
                    improved = True
                    break

    all_cust = []
    seen = set()
    for r in routes:
        for c in r:
            all_cust.append(c)
            seen.add(c)

    if len(all_cust) != n:
        missing = [i for i in range(n) if i not in seen]
        for m in missing:
            routes.append([m])

    return routes
